DROP TABLE IF EXISTS `advertise_product`;
CREATE TABLE IF NOT EXISTS `advertise_product` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category_id` int DEFAULT NULL,
  `main_image` varchar(255) NOT NULL COMMENT 'Image principale utilisée comme miniature',
  `title` varchar(255) NOT NULL,
  `title_fr` varchar(255) DEFAULT NULL,
  `title_en` varchar(255) DEFAULT NULL,
  `title_ar` varchar(255) DEFAULT NULL,
  `title_sw` varchar(255) DEFAULT NULL,
  `slug` varchar(100) DEFAULT NULL,
  `description` text,
  `description_fr` text,
  `description_en` text,
  `description_ar` text,
  `description_sw` text,
  `price` varchar(25) NOT NULL COMMENT 'Prix du produit (format texte)',
  `is_active` tinyint(1) DEFAULT '1',
  `in_vedette` tinyint(1) DEFAULT '0',
  `price_request_count` int NOT NULL DEFAULT '0' COMMENT 'Nombre de demandes de prix actualisé',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug_unique` (`slug`),
  KEY `fk_product_category` (`category_id`)
) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

