--
-- Structure de la table `commandes`
--

DROP TABLE IF EXISTS `commandes`;
CREATE TABLE IF NOT EXISTS `commandes` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `numero_commande` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` int UNSIGNED NOT NULL,
  `adresse_livraison_id` int UNSIGNED NOT NULL,
  `adresse_facturation_id` int UNSIGNED NOT NULL,
  `total_ht` decimal(15,2) NOT NULL,
  `total_tva` decimal(15,2) NOT NULL,
  `total_ttc` decimal(15,2) NOT NULL,
  `frais_livraison_ht` decimal(15,2) DEFAULT '0.00',
  `total_general_ttc` decimal(15,2) GENERATED ALWAYS AS ((`total_ttc` + (`frais_livraison_ht` * (1 + (20 / 100))))) STORED,
  `statut` enum('en_attente','confirmee','preparation','expediee','livree','annulee','remboursee') COLLATE utf8mb4_unicode_ci DEFAULT 'en_attente',
  `mode_paiement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `statut_paiement` enum('en_attente','paye','echoue','rembourse') COLLATE utf8mb4_unicode_ci DEFAULT 'en_attente',
  `transaction_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_paiement` datetime DEFAULT NULL,
  `mode_livraison` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'standard',
  `date_livraison_prevue` datetime DEFAULT NULL,
  `date_livraison_reelle` datetime DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `ip_commande` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `commandes_numero_commande_unique` (`numero_commande`),
  KEY `commandes_user_id_foreign` (`user_id`),
  KEY `commandes_statut_index` (`statut`),
  KEY `commandes_created_at_index` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

