--
-- Structure de la table `commande_lignes`
--

DROP TABLE IF EXISTS `commande_lignes`;
CREATE TABLE IF NOT EXISTS `commande_lignes` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `commande_id` int UNSIGNED NOT NULL,
  `produit_id` int UNSIGNED NOT NULL,
  `nom_produit` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_produit` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantite` int NOT NULL,
  `prix_unitaire_ht` decimal(15,2) NOT NULL,
  `taux_tva` decimal(5,2) NOT NULL,
  `total_ligne_ht` decimal(15,2) GENERATED ALWAYS AS ((`quantite` * `prix_unitaire_ht`)) STORED,
  `total_ligne_ttc` decimal(15,2) GENERATED ALWAYS AS (((`quantite` * `prix_unitaire_ht`) * (1 + (`taux_tva` / 100)))) STORED,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `commande_lignes_commande_id_foreign` (`commande_id`),
  KEY `commande_lignes_produit_id_foreign` (`produit_id`)
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

