--
-- Structure de la table `company_statements`
--

DROP TABLE IF EXISTS `company_statements`;
CREATE TABLE IF NOT EXISTS `company_statements` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` enum('mission','vision','objective','value','slogan','other') COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Type de déclaration',
  `title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Titre optionnel (ex: pour un objectif)',
  `title_fr` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `title_en` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `title_sw` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Contenu de la déclaration',
  `description_fr` text COLLATE utf8mb4_general_ci,
  `description_en` text COLLATE utf8mb4_general_ci,
  `description_sw` text COLLATE utf8mb4_general_ci,
  `icon` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Icône (ex: bx-target)',
  `order` int DEFAULT '0' COMMENT 'Ordre d''affichage',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `type` (`type`),
  KEY `is_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Déchargement des données de la table `company_statements`
--

INSERT INTO `company_statements` (`id`, `type`, `title`, `title_fr`, `title_en`, `title_sw`, `description`, `description_fr`, `description_en`, `description_sw`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'vision', 'Vision Statement', 'Déclaration de vision stratégique', 'Vision statement', 'Tamko la Dira', 'To become a leading Zambian-based model in chemical-devoid large-scale farming of organic crops and medicinal plants and industrial hub for manufacturing of innovative standardized TCAMs, Nutraceuticals/Food Supplements, phytomedicines and phytopharmaceuticals subjected to preclinical and clinical trials via our scientific research laboratory and laboratory animal breeding facility, high-nutrient organic fertilizers as well as clean-label fortified health food products and fruit beverages- recognized across African continent and globally for quality, safety and sustainability, and contribution to the sustainable socioeconomic transformation.', 'Devenir un modèle de référence basé en Zambie pour l\'agriculture biologique à grande échelle sans intrants chimiques, dédiée aux cultures biologiques et aux plantes médicinales, ainsi qu\'une plateforme industrielle de fabrication de MTCA (Médecines Traditionnelles, Complémentaires et Alternatives) innovantes et standardisées, de nutraceutiques/compléments alimentaires, de phytomédicaments et de phytopharmaceutiques soumis à des essais précliniques et cliniques via notre laboratoire de recherche scientifique et notre unité d\'élevage d\'animaux de laboratoire. L\'entreprise produira également des engrais organiques riches en nutriments, des produits alimentaires fortifiés clean-label et des boissons à base de fruits — reconnue à travers le continent africain et à l\'échelle mondiale pour la qualité, la sécurité, la durabilité et sa contribution à la transformation socioéconomique durable.', 'To become a leading Zambia-based model in large-scale chemical-free farming of organic crops and medicinal plants, as well as an industrial hub for the manufacturing of innovative and standardized TCAMs, nutraceuticals/dietary supplements, phytomedicines and phytopharmaceuticals submitted to preclinical and clinical trials via our scientific research laboratory and laboratory animal breeding facility, as well as nutrient-rich organic fertilizers and clean-label fortified food products and fruit-based beverages — recognized across the African continent and globally for quality, safety, sustainability and their contribution to sustainable socioeconomic transformation.', 'Kuwa kielelezo kikuu nchini Zambia katika kilimo kisicho na kemikali kwa kiwango kikubwa cha mazao ya kikaboni na mimea ya dawa, pamoja na kitovu cha viwanda kwa utengenezaji wa TCAMs bunifu na sanifu, virutubisho/viruzu vya lishe, dawa za mimea na dawa za mimea zinazowasilishwa kwa majaribio ya kabla ya matibabu na ya kimatibabu kupitia maabara yetu ya utafiti wa kisayansi na kituo cha kuzalia wanyama wa maabara, pamoja na mbolea za kikaboni zenye virutubisho vingi na bidhaa za chakula zilizoimarishwa na vinywaji vinavyotokana na matunda zenye lebo safi — kutambuliwa katika bara la Afrika na duniani kote kwa ubora, usalama, uendelevu na mchango wao katika mageuzi ya kijamii na kiuchumi endelevu.', 'bx-show', 1, 1, '2026-03-04 12:00:44', '2026-04-20 21:42:54'),
(2, 'mission', 'Mission Statement', 'Déclaration de mission', 'Mission statement', 'Tamko la Dhamira', 'To organically do large-scale commercial farming of key medicinal plants, functional crops, fruits and vegetables in over 2000 hectare-farmland and to process the harvest into GMPcompliant and ISO standard TCAMs, Nutraceuticals/Food Supplements, phytomedicines and phytopharmaceuticals subjected to preclinical and clinical trials via our scientific research laboratory and laboratory animal breeding facility, as well as clean-label fortified health food products and fruit beverages and high-nutrient organic fertilizers.', 'Pratiquer une agriculture biologique commerciale à grande échelle de plantes médicinales clés, de cultures fonctionnelles, de fruits et de légumes sur plus de 2 000 hectares, et transformer les récoltes en MTCA conformes aux Bonnes Pratiques de Fabrication (BPF) et aux normes ISO, en nutraceutiques/compléments alimentaires, en phytomédicaments et phytopharmaceutiques soumis à des essais précliniques et cliniques via notre laboratoire de recherche scientifique et notre unité d\'élevage d\'animaux de laboratoire, ainsi qu\'en produits alimentaires fortifiés clean-label, boissons à base de fruits et engrais organiques riches en nutriments.', 'To organically carry out large-scale commercial farming of key medicinal plants, functional crops, fruits and vegetables on over 2000 hectares, and transform harvests into GMP and ISO compliant TCAMs, nutraceuticals/dietary supplements, phytomedicines and phytopharmaceuticals submitted to preclinical and clinical trials via our scientific research laboratory and laboratory animal breeding facility, as well as clean-label fortified food products, fruit-based beverages and nutrient-rich organic fertilizers.', 'Kufanya kilimo cha kikaboni cha kibiashara kwa kiwango kikubwa cha mimea muhimu ya dawa, mazao ya kazi, matunda na mboga kwenye zaidi ya hekta 2000, na kubadilisha mavuno kuwa TCAMs zinazozingatia GMP na viwango vya ISO, virutubisho/viruzu vya lishe, dawa za mimea na dawa za mimea zinazowasilishwa kwa majaribio ya kabla ya matibabu na ya kimatibabu kupitia maabara yetu ya utafiti wa kisayansi na kituo cha kuzalia wanyama wa maabara, pamoja na bidhaa za chakula zilizoimarishwa zenye lebo safi, vinywaji vinavyotokana na matunda na mbolea za kikaboni zenye virutubisho vingi.', 'bx bx-target', 2, 1, '2026-03-04 12:00:44', '2026-04-20 21:42:54'),
(3, 'other', 'Strategic Positioning', 'Positionnement stratégique', 'Strategic positioning', 'Msimamo wa Kimkakati', 'AFRICAN GREEN FARMERS LIMITED is positioned as a vertically integrated agro-industrial company focused on high-value medicinal and functional crops. Through structured partnerships, value addition and export-oriented processing, the company transforms commercial organic agriculture into scalable industrial (TCAMs, Nutraceuticals/Food Supplements, phytomedicines and phytopharmaceuticals subjected to preclinical and clinical trials via our scientific research laboratory and laboratory animal breeding facility, as well as clean-label fortified health food products and fruit beverages.', 'AFRICAN GREEN FARMERS LIMITED se positionne comme une entreprise agro-industrielle intégrée verticalement, axée sur les cultures médicinales et fonctionnelles à forte valeur ajoutée. Grâce à des partenariats structurés, à la création de valeur et à une transformation orientée vers l\'exportation, l\'entreprise convertit l\'agriculture biologique commerciale en une production industrielle évolutive (MTCA, nutraceutiques/compléments alimentaires, phytomédicaments et phytopharmaceutiques soumis à des essais précliniques et cliniques via notre laboratoire de recherche scientifique et notre unité d\'élevage d\'animaux de laboratoire, ainsi que des produits alimentaires fortifiés clean-label et des boissons à base de fruits).', 'AFRICAN GREEN FARMERS LIMITED is positioned as a vertically integrated agro-industrial company, focused on high-value medicinal and functional crops. Through structured partnerships, value creation and export-oriented processing, the company transforms commercial organic farming into scalable industrial production (TCAMs, nutraceuticals/dietary supplements, phytomedicines and phytopharmaceuticals submitted to preclinical and clinical trials via our scientific research laboratory and laboratory animal breeding facility, as well as clean-label fortified food products and fruit-based beverages).', 'AFRICAN GREEN FARMERS LIMITED imewekwa kama kampuni ya kilimo-viwanda iliyounganishwa kiwima, inayozingatia mazao ya dawa na kazi yenye thamani ya juu. Kupitia ushirikiano uliopangwa, uundaji wa thamani na usindikaji unaolenga usafirishaji, kampuni inabadilisha kilimo hai cha kibiashara kuwa uzalishaji wa kiviwanda unaoweza kuongezeka (TCAMs, virutubisho/viruzu vya lishe, dawa za mimea na dawa za mimea zinazowasilishwa kwa majaribio ya kabla ya matibabu na ya kimatibabu kupitia maabara yetu ya utafiti wa kisayansi na kituo cha kuzalia wanyama wa maabara, pamoja na bidhaa za chakula zilizoimarishwa zenye lebo safi na vinywaji vinavyotokana na matunda).', 'bx-map-alt', 3, 1, '2026-03-04 12:00:44', '2026-04-20 21:42:54');

