  PRIMARY KEY (`id`),
  UNIQUE KEY `configurations_cle_unique` (`cle`),
  KEY `configurations_categorie_index` (`categorie`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

