--
-- Structure de la table `consultations`
--

DROP TABLE IF EXISTS `consultations`;
CREATE TABLE IF NOT EXISTS `consultations` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `patient_id` int UNSIGNED NOT NULL,
  `medecin_id` int UNSIGNED NOT NULL,
  `numero_consultation` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('video','presentiel','telephone') COLLATE utf8mb4_unicode_ci DEFAULT 'video',
  `poids` decimal(5,2) DEFAULT NULL,
  `taille` decimal(5,2) DEFAULT NULL,
  `symptomes` text COLLATE utf8mb4_unicode_ci,
  `duree_symptomes` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `consultation_precedente` enum('yes','no') COLLATE utf8mb4_unicode_ci DEFAULT 'no',
  `examens_demandes` text COLLATE utf8mb4_unicode_ci,
  `ordonnances` text COLLATE utf8mb4_unicode_ci,
  `diagnostic` text COLLATE utf8mb4_unicode_ci,
  `traitement` text COLLATE utf8mb4_unicode_ci,
  `notes_medecin` text COLLATE utf8mb4_unicode_ci,
  `date_souhaitee` datetime NOT NULL,
  `date_confirmee` datetime DEFAULT NULL,
  `date_debut` datetime DEFAULT NULL,
  `date_fin` datetime DEFAULT NULL,
  `duree_minutes` int DEFAULT '30',
  `room_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `room_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `statut` enum('en_attente','confirmee','en_cours','terminee','annulee','refusee') COLLATE utf8mb4_unicode_ci DEFAULT 'en_attente',
  `honoraires_consultation` decimal(10,2) NOT NULL DEFAULT '0.00',
  `motif_annulation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prix_ht` decimal(15,2) NOT NULL,
  `devise` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'USD',
  `tva` decimal(5,2) DEFAULT '20.00',
  `prix_ttc` decimal(15,2) GENERATED ALWAYS AS ((`prix_ht` * (1 + (`tva` / 100)))) STORED,
  `paiement_statut` enum('en_attente','paye','echoue','rembourse') COLLATE utf8mb4_unicode_ci DEFAULT 'en_attente',
  `mode_paiement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `preuve_paiement` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ip_creation` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `country_id` int UNSIGNED DEFAULT NULL,
  `age` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `consultations_numero_consultation_unique` (`numero_consultation`),
  UNIQUE KEY `consultations_room_id_unique` (`room_id`),
  KEY `consultations_patient_id_foreign` (`patient_id`),
  KEY `consultations_medecin_id_foreign` (`medecin_id`),
  KEY `consultations_statut_index` (`statut`),
  KEY `consultations_date_souhaitee_index` (`date_souhaitee`),
  KEY `consultations_country_id_foreign` (`country_id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déchargement des données de la table `consultations`
--

