--
-- Structure de la table `contact_us`
--

DROP TABLE IF EXISTS `contact_us`;
CREATE TABLE IF NOT EXISTS `contact_us` (
  `IdContact` int NOT NULL AUTO_INCREMENT,
  `FullName` varchar(250) COLLATE utf8mb4_general_ci NOT NULL,
  `Email` varchar(250) COLLATE utf8mb4_general_ci NOT NULL,
  `Subject` varchar(250) COLLATE utf8mb4_general_ci NOT NULL,
  `Message` text COLLATE utf8mb4_general_ci NOT NULL,
  `PhoneNumber` varchar(12) COLLATE utf8mb4_general_ci NOT NULL,
  `Date_creation` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Location` varchar(200) COLLATE utf8mb4_general_ci NOT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_agent` text COLLATE utf8mb4_general_ci,
  `is_readed` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`IdContact`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

