--
-- Structure de la table `documents`
--

DROP TABLE IF EXISTS `documents`;
CREATE TABLE IF NOT EXISTS `documents` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` int UNSIGNED NOT NULL COMMENT 'Propriétaire du document (patient)',
  `consultation_id` int UNSIGNED DEFAULT NULL COMMENT 'Optionnel : lien vers une consultation',
  `filename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nom du fichier sur le serveur',
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nom d’origine',
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Type MIME (pdf, image, etc.)',
  `type` enum('consultation','analyse','prescription','autre') COLLATE utf8mb4_unicode_ci DEFAULT 'autre',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `consultation_id` (`consultation_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `email_templates`
--

DROP TABLE IF EXISTS `email_templates`;
CREATE TABLE IF NOT EXISTS `email_templates` (
  `id` int NOT NULL AUTO_INCREMENT,
  `template_key` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Identifiant unique du template (ex: welcome_user, investor_confirmation)',
  `template_name` varchar(200) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Nom affiché du template',
  `subject` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Sujet de l''email',
  `body` text COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Corps de l''email (HTML)',
  `variables` text COLLATE utf8mb4_general_ci COMMENT 'Liste des variables disponibles (JSON)',
  `description` text COLLATE utf8mb4_general_ci COMMENT 'Description du template',
  `category` enum('user','investor','broker','partner','system','other') COLLATE utf8mb4_general_ci DEFAULT 'other' COMMENT 'Catégorie du template',
  `is_active` tinyint(1) DEFAULT '1' COMMENT 'Template actif ou non',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` int DEFAULT NULL COMMENT 'ID de l''utilisateur qui a créé le template',
  `updated_by` int DEFAULT NULL COMMENT 'ID de l''utilisateur qui a modifié le template',
  PRIMARY KEY (`id`),
  UNIQUE KEY `template_key` (`template_key`),
  KEY `category` (`category`),
  KEY `is_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Déchargement des données de la table `email_templates`
--

INSERT INTO `email_templates` (`id`, `template_key`, `template_name`, `subject`, `body`, `variables`, `description`, `category`, `is_active`, `created_at`, `updated_at`, `created_by`, `updated_by`) VALUES
(1, 'welcome_user', 'Bienvenue utilisateur', 'Bienvenue sur African Green Farmers', '\r\n<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <title>Bienvenue</title>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }\r\n        .container { max-width: 600px; margin: 0 auto; padding: 20px; }\r\n        .header { background: #0B4F2E; color: white; padding: 20px; text-align: center; }\r\n        .content { padding: 20px; background: #f9f9f9; }\r\n        .footer { text-align: center; padding: 20px; color: #666; font-size: 12px; }\r\n        .button { background: #0B4F2E; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"header\">\r\n            <h2>African Green Farmers</h2>\r\n        </div>\r\n        <div class=\"content\">\r\n            <h3>Bonjour {full_name},</h3>\r\n            <p>Bienvenue sur la plateforme African Green Farmers !</p>\r\n            <p>Votre compte a été créé avec succès. Vous pouvez maintenant vous connecter avec votre email : <strong>{email}</strong></p>\r\n            <p style=\"text-align: center; margin: 30px 0;\">\r\n                <a href=\"{login_url}\" class=\"button\">Se connecter</a>\r\n            </p>\r\n            <p>Cordialement,<br>L\'équipe African Green Farmers</p>\r\n        </div>\r\n        <div class=\"footer\">\r\n            <p>Cet email a été envoyé automatiquement, merci de ne pas y répondre.</p>\r\n            <p>&copy; {year} African Green Farmers. Tous droits réservés.</p>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>\r\n', '[\"full_name\", \"email\", \"login_url\", \"year\"]', 'Template de bienvenue pour les nouveaux utilisateurs', 'user', 1, '2026-02-27 14:06:35', '2026-02-27 14:06:35', NULL, NULL),
(2, 'investor_confirmation', 'Confirmation investisseur', 'Confirmation de votre expression d\'intérêt - Investisseur AGF', '\r\n<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <title>Confirmation</title>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }\r\n        .container { max-width: 600px; margin: 0 auto; padding: 20px; }\r\n        .header { background: #0B4F2E; color: white; padding: 20px; text-align: center; }\r\n        .content { padding: 20px; background: #f9f9f9; }\r\n        .footer { text-align: center; padding: 20px; color: #666; font-size: 12px; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"header\">\r\n            <h2>African Green Farmers</h2>\r\n        </div>\r\n        <div class=\"content\">\r\n            <h3>Bonjour {full_name},</h3>\r\n            <p>Nous vous remercions pour votre intérêt à rejoindre notre réseau d\'investisseurs partenaires.</p>\r\n            <p>Votre expression d\'intérêt a bien été enregistrée avec les informations suivantes :</p>\r\n            <ul>\r\n                <li><strong>Nom complet :</strong> {full_name}</li>\r\n                <li><strong>Organisation :</strong> {organization}</li>\r\n                <li><strong>Email :</strong> {email}</li>\r\n            </ul>\r\n            <p>Notre équipe va étudier votre profil et vous contactera dans les plus brefs délais.</p>\r\n            <p>Cordialement,<br><strong>L\'équipe African Green Farmers</strong></p>\r\n        </div>\r\n        <div class=\"footer\">\r\n            <p>Cet email a été envoyé automatiquement, merci de ne pas y répondre.</p>\r\n            <p>&copy; {year} African Green Farmers. Tous droits réservés.</p>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>\r\n', '[\"full_name\", \"organization\", \"email\", \"year\"]', 'Confirmation pour les investisseurs', 'investor', 1, '2026-02-27 14:06:35', '2026-02-27 14:06:35', NULL, NULL),
(3, 'broker_confirmation', 'Confirmation broker', 'Confirmation de votre inscription - Broker Partenaire AGF', '\r\n<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <title>Confirmation</title>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }\r\n        .container { max-width: 600px; margin: 0 auto; padding: 20px; }\r\n        .header { background: #0B4F2E; color: white; padding: 20px; text-align: center; }\r\n        .content { padding: 20px; background: #f9f9f9; }\r\n        .footer { text-align: center; padding: 20px; color: #666; font-size: 12px; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"header\">\r\n            <h2>African Green Farmers</h2>\r\n        </div>\r\n        <div class=\"content\">\r\n            <h3>Bonjour {full_name},</h3>\r\n            <p>Nous vous remercions pour votre intérêt à rejoindre notre réseau de brokers partenaires.</p>\r\n            <p>Votre inscription a bien été enregistrée avec les informations suivantes :</p>\r\n            <ul>\r\n                <li><strong>Nom complet :</strong> {full_name}</li>\r\n                <li><strong>Société :</strong> {firm_name}</li>\r\n                <li><strong>Email :</strong> {email}</li>\r\n            </ul>\r\n            <p>Notre équipe va étudier votre dossier et vous contactera dans les plus brefs délais.</p>\r\n            <p>Cordialement,<br><strong>L\'équipe African Green Farmers</strong></p>\r\n        </div>\r\n        <div class=\"footer\">\r\n            <p>Cet email a été envoyé automatiquement, merci de ne pas y répondre.</p>\r\n            <p>&copy; {year} African Green Farmers. Tous droits réservés.</p>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>\r\n', '[\"full_name\", \"firm_name\", \"email\", \"year\"]', 'Confirmation pour les brokers', 'broker', 1, '2026-02-27 14:06:35', '2026-02-27 14:06:35', NULL, NULL),
(4, 'partner_confirmation', 'Confirmation partenaire', 'Confirmation de votre candidature - Partenaire Intermédiaire AGF', '\r\n<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <title>Confirmation</title>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }\r\n        .container { max-width: 600px; margin: 0 auto; padding: 20px; }\r\n        .header { background: #0B4F2E; color: white; padding: 20px; text-align: center; }\r\n        .content { padding: 20px; background: #f9f9f9; }\r\n        .footer { text-align: center; padding: 20px; color: #666; font-size: 12px; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"header\">\r\n            <h2>African Green Farmers</h2>\r\n        </div>\r\n        <div class=\"content\">\r\n            <h3>Bonjour {full_name},</h3>\r\n            <p>Nous vous remercions pour votre intérêt à rejoindre notre réseau de partenaires intermédiaires.</p>\r\n            <p>Votre candidature a bien été enregistrée avec les informations suivantes :</p>\r\n            <ul>\r\n                <li><strong>Nom complet :</strong> {full_name}</li>\r\n                <li><strong>Société :</strong> {firm_name}</li>\r\n                <li><strong>Email :</strong> {email}</li>\r\n            </ul>\r\n            <p>Notre équipe va étudier votre dossier et vous contactera dans les plus brefs délais.</p>\r\n            <p>Cordialement,<br><strong>L\'équipe African Green Farmers</strong></p>\r\n        </div>\r\n        <div class=\"footer\">\r\n            <p>Cet email a été envoyé automatiquement, merci de ne pas y répondre.</p>\r\n            <p>&copy; {year} African Green Farmers. Tous droits réservés.</p>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>\r\n', '[\"full_name\", \"firm_name\", \"email\", \"year\"]', 'Confirmation pour les partenaires', 'partner', 1, '2026-02-27 14:06:35', '2026-02-27 14:06:35', NULL, NULL),
(5, 'admin_notification', 'Notification administrateur', 'Nouvelle inscription sur AGF - {type}', '\r\n<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <title>Nouvelle inscription</title>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; }\r\n        table { border-collapse: collapse; width: 100%; }\r\n        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }\r\n        th { background-color: #0B4F2E; color: white; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <h2>Nouvelle inscription {type}</h2>\r\n    <p><strong>ID :</strong> {id}</p>\r\n    <p><strong>Date :</strong> {date}</p>\r\n    \r\n    <h3>Informations</h3>\r\n    <table>\r\n        <tr><th>Champ</th><th>Valeur</th></tr>\r\n        {details}\r\n    </table>\r\n    \r\n    <p><a href=\"{admin_url}\">Voir dans l\'administration</a></p>\r\n</body>\r\n</html>\r\n', '[\"type\", \"id\", \"date\", \"details\", \"admin_url\"]', 'Notification pour les administrateurs', 'system', 1, '2026-02-27 14:06:35', '2026-02-27 14:06:35', NULL, NULL),
(6, 'reset_password', 'Réinitialisation mot de passe', 'Réinitialisation de votre mot de passe AGF', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <title>Réinitialisation mot de passe</title>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }\r\n        .container { max-width: 600px; margin: 0 auto; padding: 20px; }\r\n        .header { background: #0B4F2E; color: white; padding: 20px; text-align: center; }\r\n        .content { padding: 20px; background: #f9f9f9; }\r\n        .footer { text-align: center; padding: 20px; color: #666; font-size: 12px; }\r\n        .button { background: #0B4F2E; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"header\">\r\n            <h2>African Green Farmers</h2>\r\n        </div>\r\n        <div class=\"content\">\r\n            <h3>Bonjour {full_name},</h3>\r\n            <p>Vous avez demandé la réinitialisation de votre mot de passe.</p>\r\n            <p>Cliquez sur le bouton ci-dessous pour créer un nouveau mot de passe :</p>\r\n            <p style=\"text-align: center; margin: 30px 0;\">\r\n                <a href=\"{reset_link}\" class=\"button\">Réinitialiser mon mot de passe</a>\r\n            </p>\r\n            <p>Ce lien expirera dans 24 heures.</p>\r\n            <p>Si vous n\'avez pas demandé cette réinitialisation, ignorez cet email.</p>\r\n            <p>Cordialement,<br>L\'équipe African Green Farmers</p>\r\n        </div>\r\n        <div class=\"footer\">\r\n            <p>&copy; {year} African Green Farmers. Tous droits réservés.</p>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>\r\n', '[\"full_name\",\"reset_link\",\"year\"]', 'Template pour réinitialisation de mot de passe', 'system', 1, '2026-02-27 14:06:35', '2026-02-27 14:19:23', NULL, NULL);

