--
-- Structure de la table `evenements`
--

DROP TABLE IF EXISTS `evenements`;
CREATE TABLE IF NOT EXISTS `evenements` (
  `id_evenement` int NOT NULL AUTO_INCREMENT,
  `titre` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `description` text,
  `lieu` varchar(255) DEFAULT NULL,
  `date_debut` datetime DEFAULT NULL,
  `date_fin` datetime DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `capacite_max` int DEFAULT NULL,
  `inscriptions_actuelles` int DEFAULT '0',
  `lien_inscription` varchar(500) DEFAULT NULL,
  `est_public` tinyint(1) DEFAULT '1',
  `id_page_associee` int DEFAULT NULL,
  PRIMARY KEY (`id_evenement`),
  UNIQUE KEY `slug` (`slug`),
  KEY `id_page_associee` (`id_page_associee`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=latin1;

