--
-- Structure de la table `galerie_medias`
--

DROP TABLE IF EXISTS `galerie_medias`;
CREATE TABLE IF NOT EXISTS `galerie_medias` (
  `id_media` int NOT NULL AUTO_INCREMENT,
  `titre` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Titre du média',
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type` enum('image','video','audio','document','link','autre') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type de média (link = lien externe)',
  `sous_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fichier` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Chemin du fichier uploadé (pour types image, video, audio, document, autre)',
  `lien` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL externe (pour type link)',
  `miniature` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Chemin de la miniature (optionnel)',
  `waveform` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Chemin image waveform',
  `spectrogram` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Chemin image spectrogramme',
  `waveform_data` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Chemin fichier JSON données waveform',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Description du média',
  `description_fr` text COLLATE utf8mb4_unicode_ci,
  `description_en` text COLLATE utf8mb4_unicode_ci,
  `description_sw` text COLLATE utf8mb4_unicode_ci,
  `categorie` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Catégorie (ex: publicité, témoignage, produit)',
  `categorie_fr` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `categorie_en` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `categorie_sw` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_media` date DEFAULT NULL COMMENT 'Date de création/prise du média',
  `credits` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Crédits/auteur',
  `credits_fr` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `credits_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `credits_sw` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `taille` int DEFAULT NULL COMMENT 'Taille du fichier en octets (pour fichiers)',
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Type MIME (pour fichiers)',
  `duree` int DEFAULT NULL COMMENT 'Durée en secondes',
  `bitrate` int DEFAULT NULL COMMENT 'Bitrate en bps',
  `sample_rate` int DEFAULT NULL COMMENT 'Sample rate en Hz',
  `channels` tinyint DEFAULT NULL COMMENT 'Nombre de canaux audio',
  `metadata_id3` text COLLATE utf8mb4_unicode_ci COMMENT 'Métadonnées ID3 au format JSON',
  `converted_versions` text COLLATE utf8mb4_unicode_ci COMMENT 'Versions multi-bitrate au format JSON',
  `hls_playlist` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Chemin playlist HLS',
  `est_actif` tinyint(1) DEFAULT '1' COMMENT '0 = caché, 1 = visible',
  `a_partager_reseaux` tinyint(1) DEFAULT '0' COMMENT '1 = à partager sur les réseaux sociaux',
  `message_reseaux` text COLLATE utf8mb4_unicode_ci COMMENT 'Message personnalisé pour le partage',
  `message_reseaux_fr` text COLLATE utf8mb4_unicode_ci,
  `message_reseaux_en` text COLLATE utf8mb4_unicode_ci,
  `message_reseaux_sw` text COLLATE utf8mb4_unicode_ci,
  `contenu_texte` text COLLATE utf8mb4_unicode_ci,
  `contenu_texte_fr` text COLLATE utf8mb4_unicode_ci,
  `contenu_texte_en` text COLLATE utf8mb4_unicode_ci,
  `contenu_texte_sw` text COLLATE utf8mb4_unicode_ci,
  `required_subscription_id` int UNSIGNED DEFAULT NULL,
  `id_page_associee` int DEFAULT NULL COMMENT 'Page associée (si applicable)',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_for_whatsapp` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Partager sur WhatsApp',
  `is_for_website` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Publier sur le site web',
  `is_recording` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = enregistrement via micro',
  PRIMARY KEY (`id_media`),
  UNIQUE KEY `slug` (`slug`),
  KEY `id_page_associee` (`id_page_associee`),
  KEY `est_actif` (`est_actif`),
  KEY `a_partager_reseaux` (`a_partager_reseaux`),
  KEY `required_subscription_id` (`required_subscription_id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
