--
-- Structure de la table `hero_slides`
--

DROP TABLE IF EXISTS `hero_slides`;
CREATE TABLE IF NOT EXISTS `hero_slides` (
  `id` int NOT NULL AUTO_INCREMENT,
  `subtitle` varchar(255) NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `background_image` varchar(500) NOT NULL,
  `button_primary_text` varchar(150) DEFAULT NULL,
  `button_primary_icon` varchar(100) DEFAULT NULL,
  `button_primary_link` varchar(255) DEFAULT NULL,
  `button_secondary_text` varchar(150) DEFAULT NULL,
  `button_secondary_icon` varchar(100) DEFAULT NULL,
  `button_secondary_link` varchar(255) DEFAULT NULL,
  `slide_order` int DEFAULT '1',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=latin1;

