--
-- Structure de la table `medecins`
--

DROP TABLE IF EXISTS `medecins`;
CREATE TABLE IF NOT EXISTS `medecins` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `uuid` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` int UNSIGNED NOT NULL,
  `specialite` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `specialite_fr` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `specialite_en` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `specialite_sw` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero_licence` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `annees_experience` int DEFAULT '0',
  `diplomes` text COLLATE utf8mb4_unicode_ci,
  `diplomes_fr` text COLLATE utf8mb4_unicode_ci,
  `diplomes_en` text COLLATE utf8mb4_unicode_ci,
  `diplomes_sw` text COLLATE utf8mb4_unicode_ci,
  `langues_parlees` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `langues_parlees_fr` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `langues_parlees_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `langues_parlees_sw` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `honoraires_consultation` decimal(10,2) DEFAULT NULL,
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '$',
  `est_disponible` tinyint(1) DEFAULT '1',
  `note_moyenne` decimal(3,2) DEFAULT '0.00',
  `nombre_avis` int DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `medecins_user_id_unique` (`user_id`),
  UNIQUE KEY `medecins_numero_licence_unique` (`numero_licence`),
  KEY `medecins_specialite_index` (`specialite`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

