--
-- Structure de la table `messages_inbox`
--

DROP TABLE IF EXISTS `messages_inbox`;
CREATE TABLE IF NOT EXISTS `messages_inbox` (
  `id` int NOT NULL AUTO_INCREMENT,
  `queue_id` int NOT NULL,
  `participant_phone` varchar(50) NOT NULL,
  `groupe_id` varchar(100) DEFAULT NULL,
  `message_content` text,
  `media_type` enum('text','image','video','audio','document','sticker','location','contact') DEFAULT 'text',
  `media_id` varchar(255) DEFAULT NULL,
  `media_url` varchar(500) DEFAULT NULL,
  `media_caption` text,
  `media_filename` varchar(255) DEFAULT NULL,
  `status` enum('pending','sent','failed','read') DEFAULT 'pending',
  `sent_at` datetime DEFAULT NULL,
  `read_at` datetime DEFAULT NULL,
  `error_message` text,
  `retries` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `queue_id` (`queue_id`),
  KEY `participant_phone` (`participant_phone`),
  KEY `status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Structure de la table `miniatures_documents`
--

DROP TABLE IF EXISTS `miniatures_documents`;
CREATE TABLE IF NOT EXISTS `miniatures_documents` (
  `id_miniature` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_document` int UNSIGNED DEFAULT NULL,
  `chemin_miniature` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type_miniature` enum('THUMBNAIL','APERÇU','EXTRAIT_AUDIO') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_miniature`),
  KEY `id_document` (`id_document`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `mode_payement`
--

DROP TABLE IF EXISTS `mode_payement`;
CREATE TABLE IF NOT EXISTS `mode_payement` (
  `id_mode_payement` int NOT NULL AUTO_INCREMENT,
  `description` varchar(200) COLLATE utf8mb4_general_ci NOT NULL,
  `etapepaiement` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Étape de paiement (ex: initial, final, etc.)',
  `numero_compte` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Numéro de compte/compte marchand pour ce mode de paiement',
  `nom_compte` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Nom associé au compte',
  `est_actif` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id_mode_payement`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

