--
-- Structure de la table `order_requests`
--

DROP TABLE IF EXISTS `order_requests`;
CREATE TABLE IF NOT EXISTS `order_requests` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL COMMENT 'ID du produit commandé',
  `customer_name` varchar(255) NOT NULL COMMENT 'Nom complet du client',
  `customer_phone` varchar(50) NOT NULL COMMENT 'Numéro de téléphone',
  `customer_country` varchar(100) NOT NULL COMMENT 'Pays',
  `customer_city` varchar(100) NOT NULL COMMENT 'Ville',
  `customer_address` text NOT NULL COMMENT 'Adresse de livraison',
  `customer_notes` text COMMENT 'Notes supplémentaires',
  `product_title` varchar(255) NOT NULL COMMENT 'Titre du produit au moment de la commande',
  `product_price` varchar(50) NOT NULL COMMENT 'Prix affiché au moment de la commande',
  `order_status` enum('pending','processing','completed','cancelled') DEFAULT 'pending' COMMENT 'Statut de la commande',
  `whatsapp_sent` tinyint(1) DEFAULT '0' COMMENT 'Message WhatsApp envoyé',
  `whatsapp_sent_at` timestamp NULL DEFAULT NULL COMMENT 'Date d''envoi WhatsApp',
  `ip_address` varchar(45) DEFAULT NULL COMMENT 'Adresse IP du client',
  `user_agent` text COMMENT 'Navigateur du client',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_customer_phone` (`customer_phone`),
  KEY `idx_order_status` (`order_status`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=MyISAM AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

