--
-- Structure de la table `pages`
--

DROP TABLE IF EXISTS `pages`;
CREATE TABLE IF NOT EXISTS `pages` (
  `id_page` int NOT NULL AUTO_INCREMENT,
  `titre_page` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `titre_page_fr` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `titre_page_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `titre_page_ar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `titre_page_sw` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `menu_ordre` int DEFAULT '0',
  `menu_parent_id` int DEFAULT NULL,
  `est_publiee` tinyint(1) DEFAULT '1',
  `date_creation` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `date_modification` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `meta_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `meta_description_fr` mediumtext COLLATE utf8mb4_unicode_ci,
  `meta_description_en` mediumtext COLLATE utf8mb4_unicode_ci,
  `meta_description_ar` mediumtext COLLATE utf8mb4_unicode_ci,
  `meta_description_sw` mediumtext COLLATE utf8mb4_unicode_ci,
  `meta_keywords` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `contenu_page_fr` longtext COLLATE utf8mb4_unicode_ci,
  `contenu_page_en` longtext COLLATE utf8mb4_unicode_ci,
  `contenu_page_ar` longtext COLLATE utf8mb4_unicode_ci,
  `contenu_page_sw` longtext COLLATE utf8mb4_unicode_ci,
  `template_specifique` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'default',
  `icone_menu` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id_page`),
  UNIQUE KEY `slug` (`slug`),
  KEY `menu_parent_id` (`menu_parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

