(1, 'Home', 'Accueil', 'Home', 'الرئيسية', 'Nyumbani', 'home', 1, NULL, 1, '2026-02-25 17:03:01', '2026-04-14 18:28:53', 'AGF - Zambian agro-industrial biotechnology enterprise. USD 40+ million vision 2026-2031.', 'AGF - Zambian agro-industrial biotechnology enterprise. USD 40+ million vision 2026-2031.', 'AGF - Zambian agro-industrial biotechnology enterprise. USD 40+ million vision 2026-2031.', 'AGF - Zambian agro-industrial biotechnology enterprise. USD 40+ million vision 2026-2031.', 'AGF - Zambian agro-industrial biotechnology enterprise. USD 40+ million vision 2026-2031.', '', '<div class=\"hero\"><h1>Bienvenue chez AGF NuFoTEc</h1><p>Leader en biotechnologie agro-industrielle en Zambie</p></div><div class=\"features\"><div class=\"feature\"><h3>Innovation</h3><p>Recherche et développement de pointe</p></div><div class=\"feature\"><h3>Durabilité</h3><p>Engagement environnemental et social</p></div><div class=\"feature\"><h3>Qualité</h3><p>Standards GMP et certification internationale</p></div></div>', '<div class=\"hero\"><h1>Welcome to AGF NuFoTEc</h1><p>Leader in agro-industrial biotechnology in Zambia</p></div><div class=\"features\"><div class=\"feature\"><h3>Innovation</h3><p>Cutting-edge research and development</p></div><div class=\"feature\"><h3>Sustainability</h3><p>Environmental and social commitment</p></div><div class=\"feature\"><h3>Quality</h3><p>GMP standards and international certification</p></div></div>', '<div class=\"hero\"><h1>?????? ??? ?? AGF NuFoTEc</h1><p>?????? ?? ???? ??????????? ??????? ???????? ?? ??????</p></div><div class=\"features\"><div class=\"feature\"><h3>??????</h3><p>??? ?????? ?????</p></div><div class=\"feature\"><h3>???????</h3><p>???????? ?????? ??????????</p></div><div class=\"feature\"><h3>????</h3><p>?????? GMP ???????? ???????</p></div></div>', '<div class=\"hero\"><h1>Karibu AGF NuFoTEc</h1><p>Kiongozi katika bioteknolojia ya kilimo nchini Zambia</p></div><div class=\"features\"><div class=\"feature\"><h3>Ubunifu</h3><p>Utafiti na maendeleo ya kisasa</p></div><div class=\"feature\"><h3>Uendelevu</h3><p>Kujitolea kwa mazingira na kijamii</p></div><div class=\"feature\"><h3>Ubora</h3><p>Viwango vya GMP na vyeti vya kimataifa</p></div></div>', 'home', '', NULL),
(2, 'About', 'À propos', 'About', 'معلومات عنا', 'Kuhusu', 'about', 2, NULL, 1, '2026-02-25 17:03:01', '2026-04-14 18:28:53', 'Discover AGF: vertically integrated Zambian agro-industrial biotechnology company', 'Discover AGF: vertically integrated Zambian agro-industrial biotechnology company', 'Discover AGF: vertically integrated Zambian agro-industrial biotechnology company', 'Discover AGF: vertically integrated Zambian agro-industrial biotechnology company', 'Discover AGF: vertically integrated Zambian agro-industrial biotechnology company', '', '<h1>À propos de AGF NuFoTEc</h1><p>AGF NuFoTEc est une entreprise innovante spécialisée dans la biotechnologie agro-industrielle en Zambie.</p><h2>Notre histoire</h2><p>Fondée en 2019, nous avons pour mission de transformer le secteur pharmaceutique en Afrique.</p><h2>Nos valeurs</h2><ul><li>Innovation</li><li>Qualité</li><li>Durabilité</li><li>Intégrité</li></ul>', '<h1>About AGF NuFoTEc</h1><p>AGF NuFoTEc is an innovative company specialized in agro-industrial biotechnology in Zambia.</p><h2>Our Story</h2><p>Founded in 2019, we aim to transform the pharmaceutical sector in Africa.</p><h2>Our Values</h2><ul><li>Innovation</li><li>Quality</li><li>Sustainability</li><li>Integrity</li></ul>', '<h1>??? AGF NuFoTEc</h1><p>AGF NuFoTEc ?? ???? ?????? ?????? ?? ??????????? ??????? ???????? ?? ??????.</p><h2>?????</h2><p>????? ?? ??? 2019? ????? ??? ????? ???? ??????? ?? ???????.</p><h2>?????</h2><ul><li>??????</li><li>????</li><li>???????</li><li>?????</li></ul>', '<h1>Kuhusu AGF NuFoTEc</h1><p>AGF NuFoTEc ni kampuni bunifu iliyobobea katika bioteknolojia ya kilimo nchini Zambia.</p><h2>Hadithi Yetu</h2><p>Ilianzishwa mwaka 2019, tunalenga kubadilisha sekta ya dawa barani Afrika.</p><h2>Maadili Yetu</h2><ul><li>Ubunifu</li><li>Ubora</li><li>Uendelevu</li><li>Uadilifu</li></ul>', 'about', '', NULL),
