--
-- Structure de la table `paiements`
--

DROP TABLE IF EXISTS `paiements`;
CREATE TABLE IF NOT EXISTS `paiements` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `consultation_id` int UNSIGNED NOT NULL,
  `prix_ttc` decimal(10,2) NOT NULL COMMENT 'Montant total payé',
  `devise` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD' COMMENT 'USD, BIF, EUR...',
  `payment_date` datetime NOT NULL COMMENT 'Date du paiement',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `consultation_id` (`consultation_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `paniers`
--

DROP TABLE IF EXISTS `paniers`;
CREATE TABLE IF NOT EXISTS `paniers` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` int UNSIGNED DEFAULT NULL,
  `visitor_token` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_ht` decimal(15,2) DEFAULT '0.00',
  `total_ttc` decimal(15,2) DEFAULT '0.00',
  `nombre_articles` int DEFAULT '0',
  `est_actif` tinyint(1) DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `paniers_user_id_foreign` (`user_id`),
  KEY `paniers_session_id_index` (`visitor_token`)
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

