--
-- Structure de la table `panier_lignes`
--

DROP TABLE IF EXISTS `panier_lignes`;
CREATE TABLE IF NOT EXISTS `panier_lignes` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `panier_id` int UNSIGNED NOT NULL,
  `produit_id` int UNSIGNED NOT NULL,
  `quantite` int NOT NULL,
  `prix_unitaire_ht` decimal(15,2) NOT NULL,
  `taux_tva` decimal(5,2) NOT NULL,
  `total_ligne_ht` decimal(15,2) GENERATED ALWAYS AS ((`quantite` * `prix_unitaire_ht`)) STORED,
  `total_ligne_ttc` decimal(15,2) GENERATED ALWAYS AS (((`quantite` * `prix_unitaire_ht`) * (1 + (`taux_tva` / 100)))) STORED,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `panier_lignes_panier_id_foreign` (`panier_id`),
  KEY `panier_lignes_produit_id_foreign` (`produit_id`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

