--
-- Structure de la table `partenaires`
--

DROP TABLE IF EXISTS `partenaires`;
CREATE TABLE IF NOT EXISTS `partenaires` (
  `id_partenaire` int NOT NULL AUTO_INCREMENT,
  `type_partenaire` enum('outgrower','client_export','fournisseur','institutionnel','scientifique','financier','regulateur') NOT NULL,
  `nom` varchar(255) NOT NULL,
  `logo_url` varchar(500) DEFAULT NULL,
  `description` text,
  `pays` varchar(100) DEFAULT NULL,
  `site_web` varchar(255) DEFAULT NULL,
  `niveau_partenariat` enum('strategique','technique','commercial','academique') DEFAULT 'commercial',
  `date_debut` date DEFAULT NULL,
  `est_actif` tinyint(1) DEFAULT '1',
  `id_page_associee` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_partenaire`),
  KEY `id_page_associee` (`id_page_associee`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=latin1;

