-- --------------------------------------------------------

--
-- Structure de la table `participants_whatsapp`
--

DROP TABLE IF EXISTS `participants_whatsapp`;
CREATE TABLE IF NOT EXISTS `participants_whatsapp` (
  `id` int NOT NULL AUTO_INCREMENT,
  `groupe_id` varchar(100) NOT NULL,
  `participant_phone` varchar(50) NOT NULL,
  `participant_name` varchar(255) DEFAULT NULL,
  `is_blocked` tinyint(1) DEFAULT '0',
  `violation_count` int DEFAULT '0',
  `joined_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `last_active` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_participant_groupe` (`groupe_id`,`participant_phone`),
  KEY `participant_phone` (`participant_phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Structure de la table `pays`
--

DROP TABLE IF EXISTS `pays`;
CREATE TABLE IF NOT EXISTS `pays` (
