  `Formal_Name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Sub_Type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Sovereignty` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Capital` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ISO_4217_Currency_Code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ISO_4217_Currency_Name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ITU_T_Telephone_Code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ISO_3166_1_2_Letter_Code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ISO_3166_1_3_Letter_Code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ISO_3166_1_Number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `IANA_Country_Code_TLD` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=273 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

