DROP TABLE IF EXISTS `publication_documents`;
CREATE TABLE IF NOT EXISTS `publication_documents` (
  `id_document` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `titre` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type_document` enum('AUDIO','VIDEO','PHOTO','LIEN_WEB','PDF','EBOOK','DOCUMENT_TEXTE','TEXTE','AUTRE') COLLATE utf8mb4_unicode_ci NOT NULL,
