DROP TABLE IF EXISTS `sections_contenu`;
CREATE TABLE IF NOT EXISTS `sections_contenu` (
  `id_section` int NOT NULL AUTO_INCREMENT,
  `id_page` int NOT NULL,
  `type_section` enum('hero','texte','image_texte','html','grille','grille_card','grille_inline','liste_card','liste','liste_inline','liste_item','tableau','timeline') COLLATE utf8mb4_unicode_ci NOT NULL,
  `titre_section` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `titre_section_fr` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `titre_section_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `titre_section_sw` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sous_titre` mediumtext COLLATE utf8mb4_unicode_ci,
  `sous_titre_fr` mediumtext COLLATE utf8mb4_unicode_ci,
  `sous_titre_en` mediumtext COLLATE utf8mb4_unicode_ci,
  `sous_titre_sw` mediumtext COLLATE utf8mb4_unicode_ci,
  `contenu_texte` longtext COLLATE utf8mb4_unicode_ci,
  `contenu_texte_fr` longtext COLLATE utf8mb4_unicode_ci,
  `contenu_texte_en` longtext COLLATE utf8mb4_unicode_ci,
  `contenu_texte_sw` longtext COLLATE utf8mb4_unicode_ci,
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_droite` tinyint(1) DEFAULT '0',
  `bouton_texte` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bouton_texte_fr` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bouton_texte_en` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bouton_texte_sw` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bouton_lien` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ordre` int DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `custom_class` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `options_json` longtext COLLATE utf8mb4_unicode_ci,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `est_active` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`id_section`),
  KEY `id_page` (`id_page`)
) ;

