INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(38, 1, 'image_texte', 'Consult a Healthcare Professional, Wherever You Are', 'Consult a Healthcare Professional, Wherever You Are', 'Consult a healthcare professional, wherever you are.', 'Wasiliana na mtaalamu wa afya, popote ulipo.', 'Simple, Fast, and Secure Teleconsultation with Qualified Agents at Your Service', 'Simple, Fast, and Secure Teleconsultation with Qualified Agents at Your Service', 'Simple, fast and secure teleconsultation with qualified agents at your service.', 'Ushauri wa kijijini rahisi, wa haraka na salama kwa mawakala waliohitimu walioko kwenye huduma yako.', '<p>Access reliable and secure teleconsultation services in just a few clicks. Our platform connects you with qualified agents and healthcare professionals who are available to respond to your needs quickly and efficiently. Whether you need medical advice, follow-up care, or guidance, we support you remotely with confidentiality and professionalism. Avoid unnecessary travel and long waiting times: book your appointment online and consult from the comfort of your home, anytime. Our priority is to provide you with an accessible, human</p>', '<p>Access reliable and secure teleconsultation services in just a few clicks. Our platform connects you with qualified agents and healthcare professionals who are available to respond to your needs quickly and efficiently. Whether you need medical advice, follow-up care, or guidance, we support you remotely with confidentiality and professionalism. Avoid unnecessary travel and long waiting times: book your appointment online and consult from the comfort of your home, anytime. Our priority is to provide you with an accessible, human</p>', '<p>Access reliable and secure teleconsultation services in just a few clicks. Our platform connects you with qualified agents and healthcare professionals available to respond quickly and effectively to your needs. Whether you need medical advice, follow-up or guidance, we support you remotely with confidentiality and professionalism. Avoid unnecessary travel and long waits: book your appointment online and consult from home, at any time. Our priority is to offer you an accessible, human and secure service.</p>', '<p>Pata huduma za ushauri wa kijijini za kuaminika na salama kwa kubofya chache. Jukwaa letu linakuunganisha na mawakala waliohitimu na wataalamu wa afya walio tayari kukidhi mahitaji yako haraka na kwa ufanisi. Iwe unahitaji ushauri wa kitiba, ufuatiliaji au ushauri, tunakusaidia kwa mbali kwa usiri na uwelekezi. Epuka safari zisizo za lazima na kusubiri kwa muda mrefu: weka miadi yako mtandaoni na wasiliana kutoka nyumbani, wakati wowote. Kipaumbele chetu ni kukupa huduma inayopatikana, ya kibinadamu na salama.</p>', '/attachments/Sections/2026022713194869a17dd42b5fc.jpg', 0, 'Prendre Rendez-Vous', 'Prendre Rendez-Vous', 'Book an Appointment', 'Weka Miadi', 'Medicins', 3, '2026-03-01 15:44:36', 'primary', NULL, '2026-03-02 13:22:25', NULL, 1),
(58, 2, 'hero', '', NULL, NULL, NULL, 'AGF-PHYTOMED INDUSTRIES', NULL, NULL, NULL, '', NULL, NULL, NULL, '/attachments/Sections/2026030119144869a47408b4280.jpg', 0, '', NULL, NULL, NULL, '', 1, '2026-03-01 15:44:36', '', NULL, '2026-03-02 14:57:59', NULL, 1),
(111, 3, 'texte', 'Background & Strategic Rationale', 'Background & Strategic Rationale', 'Context and strategic justification', 'Muktadha na uhalali wa kimkakati', 'Background & Strategic Rationale ', 'Background & Strategic Rationale ', 'Context and strategic justification', 'Muktadha na uhalali wa kimkakati', '<p class=\"MsoNormal\" style=\"margin: 0cm 3.75pt .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Zambia, like many African nations, is endowed with a rich biodiversity of medicinal plants and a strong cultural heritage of traditional medicine use. However, the Traditional, Complementary and Alternative Medicines (TCAMs) sector remains largely underdeveloped, characterized by rudimentary practices, lack of standardization, minimal research support, and the absence of modern manufacturing infrastructure. Despite growing political will, recognition by the Ministry of Health, and the establishment of regulatory bodies such as ZAMRA, the country still lacks the necessary technological capacity to transform traditional herbal knowledge into high-quality, safe, and standardized health products.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .65pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">African Green Farmers Limited is structured, via its AGF-PHYTOMED Industries Facility, as a vertically integrated, GMP-aligned and ISO standard agro-biotechnology and phytopharmaceutical manufacturing platform designed to capture high-growth demand for plant-based preventive and therapeutic health products across domestic and regional markets. By scaling commercial organic cultivation from 90 hectares to over 2,000 hectares of high-value medicinal and nutrient-dense crops, including Aloe vera and Carica papaya, and deploying USD 40+ million into advanced processing infrastructure, cleanroom manufacturing environments, phytochemical and microbiological laboratories, and ISOcertified quality systems, AGF secures raw material traceability, establishes strong barriers to entry, optimizes value addition margins, and reduces regional import dependency. The diversified product architecture&mdash;spanning standardized <span style=\"font-family: \'Calibri\',sans-serif; mso-fareast-font-family: Calibri;\">TCAMs</span>, nutraceuticals, clean-label fortified functional foods, high-nutrient organic fertilizers, clinically validated phytomedicines and phytopharmaceuticals&mdash;creates layered revenue streams with early cash-flow generation and long-term high-margin phytopharmaceutical positioning, targeting multi-million-dollar annual turnover, sustainable EBITDA performance, and scalable export expansion by 2031.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .9pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">AGF-PHYTOMED INDUSTRIES facility emerges as one of leading Zambian private initiatives to implement state-of-the-art, fully integrated and automated industrial solutions in the herbal and nutraceutical sector. The company has adopted rare customized and automated Advanced GMP-Compliant and ISO- standards Turnkey Production Complex for Herbal API (<span style=\"background: #FBD4B4;\">Active Pharmaceutical Ingredients</span>) Extraction, Encapsulation and Tableting line system. This complex industrial-scale and automated setup ―<em style=\"mso-bidi-font-style: normal;\">TURNKEY </em></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm 1.6pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\"><em style=\"mso-bidi-font-style: normal;\">ULTRASOUND-ASSISTED EXTRACTION (UAE), CAPSULE PRODUCTION AND </em></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\"><em style=\"mso-bidi-font-style: normal;\">TABLETING LINE SYSTEM</em>‖ combines three advanced processing techniques:<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .05pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">1)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Phyotochemical Extraction and Purification Process- Post-harvest processing, eventual defatting, concentration, eventual purification. vacuum drying and packaging the extract for storage;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">2)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Capsule Manufacturing Process- Encapsulation, bottle filling, capping and sealing, bottle instructional labeling, bottle cartoning, leaflet<span style=\"mso-spacerun: yes;\">&nbsp; </span>inserting and sealing and case packaging of 15 bottles;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">3)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Tablet Manufacturing Process- Dry extract blending, granulation, eventual vacuum drying, fluid bed dryer, tablet compression, tablet coating, bottle filing, capping, bottle sealing,<span style=\"mso-spacerun: yes;\">&nbsp; </span>bottle instructional labeling, bottle cartoning, instructional leaflet inserting as well as the case packaging of 15 bottles.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">The line system operates at reduced temperatures (40&ndash;60&deg;C) to preserve heat-sensitive active pharmaceutical ingredients (Bioactive compounds) targeted to develop biologically safe and effective herbal medicines, Nutraceuticals, nutrient-dense fortified health food products and high-nutrient organic fertilizer&mdash;unprecedented cutting-edge technology in Zambia&rsquo;s TCAM/phytomedicine sector.</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"color: red;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></p>', '<p class=\"ds-markdown-paragraph\"><strong>Zambie, comme de nombreux pays africains, est dot&eacute;e d\'une riche biodiversit&eacute; de plantes m&eacute;dicinales et d\'un fort h&eacute;ritage culturel d\'utilisation de la m&eacute;decine traditionnelle. Cependant, le secteur des M&eacute;decines Traditionnelles, Compl&eacute;mentaires et Alternatives (MTCA) reste largement sous-d&eacute;velopp&eacute;, caract&eacute;ris&eacute; par des pratiques rudimentaires, un manque de standardisation, un soutien minimal &agrave; la recherche et l\'absence d\'infrastructures de fabrication modernes. Malgr&eacute; une volont&eacute; politique croissante, une reconnaissance par le Minist&egrave;re de la Sant&eacute; et la mise en place d\'organismes de r&eacute;glementation tels que la ZAMRA, le pays ne dispose toujours pas des capacit&eacute;s technologiques n&eacute;cessaires pour transformer les connaissances traditionnelles &agrave; base de plantes en produits de sant&eacute; de haute qualit&eacute;, s&ucirc;rs et standardis&eacute;s.</strong></p>\r\n<p class=\"ds-markdown-paragraph\"><strong>African Green Farmers Limited est structur&eacute;e, par l\'interm&eacute;diaire de son installation AGF-PHYTOMED Industries, en tant que plateforme de fabrication agro-biotechnologique et phytopharmaceutique verticalement int&eacute;gr&eacute;e, conforme aux normes GMP et ISO, con&ccedil;ue pour capter la demande &agrave; forte croissance de produits de sant&eacute; pr&eacute;ventifs et th&eacute;rapeutiques &agrave; base de plantes sur les march&eacute;s nationaux et r&eacute;gionaux. En d&eacute;veloppant la culture biologique commerciale de 90 hectares &agrave; plus de 2 000 hectares de cultures m&eacute;dicinales et nutritives &agrave; haute valeur ajout&eacute;e, notamment l\'Aloe vera et le Carica papaya, et en investissant plus de 40 millions USD dans des infrastructures de transformation avanc&eacute;es, des environnements de fabrication en salle blanche, des laboratoires phytochimiques et microbiologiques, ainsi que des syst&egrave;mes qualit&eacute; certifi&eacute;s ISO, AGF garantit la tra&ccedil;abilit&eacute; des mati&egrave;res premi&egrave;res, &eacute;tablit des barri&egrave;res &agrave; l\'entr&eacute;e solides, optimise les marges &agrave; valeur ajout&eacute;e et r&eacute;duit la d&eacute;pendance r&eacute;gionale aux importations. L\'architecture diversifi&eacute;e des produits &mdash; couvrant les MTCA standardis&eacute;s, les nutraceutiques, les aliments fonctionnels enrichis &agrave; &eacute;tiquette propre, les engrais organiques riches en nutriments, les phytom&eacute;dicaments et phytopharmaceutiques cliniquement valid&eacute;s &mdash; cr&eacute;e des flux de revenus superpos&eacute;s avec une g&eacute;n&eacute;ration pr&eacute;coce de tr&eacute;sorerie et un positionnement phytopharmaceutique &agrave; long terme &agrave; forte marge, visant un chiffre d\'affaires annuel de plusieurs millions de dollars, une performance d\'EBITDA durable et une expansion exportable &agrave; l\'&eacute;chelle d\'ici 2031.</strong></p>\r\n<p class=\"ds-markdown-paragraph\"><strong>L\'installation AGF-PHYTOMED INDUSTRIES se positionne comme l\'une des principales initiatives priv&eacute;es zambiennes visant &agrave; mettre en &oelig;uvre des solutions industrielles automatis&eacute;es, enti&egrave;rement int&eacute;gr&eacute;es et de pointe dans le secteur des plantes m&eacute;dicinales et des nutraceutiques. La soci&eacute;t&eacute; a adopt&eacute; un complexe de production cl&eacute; en main rare, personnalis&eacute; et automatis&eacute;, conforme aux normes GMP avanc&eacute;es et aux normes ISO, pour l\'extraction d\'API (Principes Actifs Pharmaceutiques) &agrave; base de plantes, ainsi qu\'un syst&egrave;me de lignes d\'encapsulation et de comprim&eacute;s. Ce complexe industriel automatis&eacute; &agrave; l\'&eacute;chelle industrielle &mdash; &laquo; SYST&Egrave;ME DE LIGNE D\'EXTRACTION PAR ULTRASONS (UAE), DE PRODUCTION DE G&Eacute;LULES ET DE COMPRIM&Eacute;S &raquo; &mdash; combine trois techniques de transformation avanc&eacute;es :</strong></p>\r\n<p class=\"ds-markdown-paragraph\"><strong>1) Proc&eacute;d&eacute; d\'extraction et de purification phytochimique &mdash; Traitement post-r&eacute;colte, d&eacute;graissage &eacute;ventuel, concentration, purification &eacute;ventuelle, s&eacute;chage sous vide et conditionnement de l\'extrait pour stockage ;</strong></p>\r\n<p class=\"ds-markdown-paragraph\"><strong>2) Proc&eacute;d&eacute; de fabrication de g&eacute;lules &mdash; Encapsulation, remplissage des flacons, capsulage et scellage, &eacute;tiquetage des flacons, mise en carton des flacons, insertion des notices et conditionnement en caisse de 15 flacons ;</strong></p>\r\n<p class=\"ds-markdown-paragraph\"><strong>3) Proc&eacute;d&eacute; de fabrication de comprim&eacute;s &mdash; M&eacute;lange d\'extrait sec, granulation, s&eacute;chage sous vide &eacute;ventuel, s&eacute;cheur &agrave; lit fluidis&eacute;, compression des comprim&eacute;s, enrobage des comprim&eacute;s, remplissage des flacons, capsulage, scellage des flacons, &eacute;tiquetage des flacons, mise en carton des flacons, insertion des notices ainsi que le conditionnement en caisse de 15 flacons.</strong></p>\r\n<p class=\"ds-markdown-paragraph\"><strong>Le syst&egrave;me de ligne fonctionne &agrave; des temp&eacute;ratures r&eacute;duites (40&ndash;60&deg;C) pour pr&eacute;server les principes actifs pharmaceutiques thermosensibles (compos&eacute;s bioactifs), visant &agrave; d&eacute;velopper des m&eacute;dicaments &agrave; base de plantes biologiquement s&ucirc;rs et efficaces, des nutraceutiques, des produits alimentaires de sant&eacute; enrichis riches en nutriments et des engrais organiques &agrave; haute valeur nutritive &mdash; une technologie de pointe sans pr&eacute;c&eacute;dent dans le secteur des MTCA/phytom&eacute;dicaments en Zambie.</strong></p>', '<p class=\"MsoNormal\" style=\"margin: 0cm 3.75pt .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Burundi, like many African nations, is endowed with rich biodiversity of medicinal plants and a strong cultural heritage of using traditional medicine. However, the sector of Traditional, Complementary and Alternative Medicines (TCAMs) remains largely underdeveloped, characterized by rudimentary practices, lack of standardization, minimal research support and lack of modern manufacturing infrastructure. Despite growing political will, recognition by the Ministry of Health and the establishment of regulatory bodies such as ZAMRA, the country still lacks the technological capacity needed to transform traditional knowledge into high-quality, safe and standardized health products.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .65pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">NUFOTEC-PHYTOMED Industries is structured, through its NUFOTEC-PHYTOMED Industries facility, as a vertically integrated agro-biotechnological and phytopharmaceutical manufacturing platform, aligned with GMP and ISO standards, designed to capture the high growth demand for preventive and therapeutic plant-based health products in domestic and regional markets. By expanding commercial organic farming from 90 hectares to over 2,000 hectares of medicinal and high-value nutrient-rich crops, including Aloe vera and Carica papaya, and deploying over USD 40 million in advanced processing infrastructure, cleanroom manufacturing environments, phytochemical and microbiological laboratories and ISO certified quality systems, NUFOTEC ensures raw material traceability, establishes strong entry barriers, optimizes value-added margins and reduces dependence on regional imports. The diversified product architecture &ndash; covering standardized TCAMs, nutraceuticals, clean-label fortified functional foods, nutrient-rich organic fertilizers, clinically validated phytomedicines and phytopharmaceuticals &ndash; creates stacked revenue streams with early cash generation and long-term high-margin phytopharmaceutical positioning, aiming for several million USD annual turnover, sustainable EBITDA performance and scalable export expansion by 2031.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .9pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">The NUFOTEC-PHYTOMED INDUSTRIES facility emerges as one of the main Zambian private initiatives to implement automated, fully integrated and cutting-edge industrial solutions in the herbs and nutraceuticals sector. The company has adopted a rare, customized, automated turnkey production line system compliant with GMP and ISO standards for the extraction, encapsulation and tableting of plant-based Active Pharmaceutical Ingredients (APIs). This complex and automated industrial configuration ―TURNKEY ULTRASOUND-ASSISTED EXTRACTION (UAE), CAPSULE PRODUCTION AND TABLETING LINE SYSTEM‖ combines three advanced processing techniques:<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .05pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">1)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Phytochemical extraction and purification process &ndash; Post-harvest treatment, possible degreasing, concentration, possible purification, vacuum drying and packaging of the extract for storage;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">2)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Capsule manufacturing process &ndash; Encapsulation, bottle filling, capping and sealing, bottle labeling, bottle boxing, leaflet insertion and sealing and packing in a case of 15 bottles;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">3)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Tablet manufacturing process &ndash; Dry extract mixing, granulation, possible vacuum drying, fluid bed dryer, tablet compression, tablet coating, bottle filling, capping, bottle sealing, bottle labeling, bottle boxing, leaflet insertion and packaging in a case of 15 bottles.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">The line system operates at reduced temperatures (40&ndash;60&deg;C) to preserve thermosensitive pharmaceutical active ingredients (bioactive compounds) targeted to develop safe and effective phytomedicines, nutraceuticals, nutrient-rich fortified health foods and nutrient-rich organic fertilizers &ndash; a cutting-edge technology unprecedented in the TCAMs/phytomedicine sector in Zambia.</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"color: red;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></p>', '<p class=\"MsoNormal\" style=\"margin: 0cm 3.75pt .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Burundi, kama mataifa mengi ya Kiafrika, ina bayoanuwai tajiri ya mimea ya dawa na urithi thabiti wa kitamaduni wa matumizi ya dawa za jadi. Hata hivyo, sekta ya Dawa za Jadi, Ziada na Mbadala (TCAMs) bado haijaendelezwa kwa kiasi kikubwa, inayojulikana kwa mazoea ya kienyeji, ukosefu wa usanifishaji, msaada mdogo wa utafiti na ukosefu wa miundombinu ya kisasa ya utengenezaji. Licha ya nia inayoongezeka ya kisiasa, kutambuliwa na Wizara ya Afya na kuanzishwa kwa vyombo vya udhibiti kama vile ZAMRA, nchi bado inakosa uwezo wa kiteknolojia unaohitajika kubadilisha maarifa ya jadi kuwa bidhaa za afya za ubora wa juu, salama na sanifu.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .65pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">NUFOTEC-PHYTOMED Industries imeundwa, kupitia kituo chake cha NUFOTEC-PHYTOMED Industries, kama jukwaa la utengenezaji wa kilimo-bioteknolojia na dawa za mimea lililojumuishwa kiwima, linalolingana na viwango vya GMP na ISO, iliyoundwa kunyanyua mahitaji ya ukuaji wa juu wa bidhaa za afya za kuzuia na za matibabu zinazotokana na mimea katika masoko ya ndani na ya kikanda. Kwa kupanua kilimo cha kibiashara cha kikaboni kutoka hekta 90 hadi zaidi ya hekta 2,000 za mimea ya dawa na mazao yenye virutubisho vya thamani ya juu, ikiwa ni pamoja na Aloe vera na Carica papaya, na kupeleka zaidi ya USD milioni 40 katika miundombinu ya hali ya juu ya usindikaji, mazingira ya utengenezaji wa vyumba safi, maabara za fitokemikali na kibiolojia na mifumo ya ubora iliyoidhinishwa na ISO, NUFOTEC inahakikisha ufuatiliaji wa malighafi, inaweka vizuizi vikali vya kuingia, inaboresha ukingo wa thamani iliyoongezwa na kupunguza utegemezi wa uagizaji kutoka kikanda. Muundo wa bidhaa uliobadilishana &ndash; unaojumuisha TCAMs sanifu, virutubisho, vyakula vya kazi vilivyoimarishwa lebo-safi, mbolea za kikaboni zenye virutubisho vingi, dawa za mimea na dawa za mimea zilizothibitishwa kikliniki &ndash; huunda mtiririko wa mapato yaliyowekwa juu na uzalishaji wa mapema wa fedha na msimamo wa muda mrefu wa dawa za mimea wenye kiwango cha juu cha faida, ukilenga mauzo ya kila mwaka ya milioni kadhaa za USD, utendaji endelevu wa EBITDA na upanuzi wa mauzo ya nje unaoweza kuongezeka kufikia 2031.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .9pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Kituo cha NUFOTEC-PHYTOMED INDUSTRIES kinaibuka kama mojawapo ya mipango binafsi mikuu ya Zambia ya kutekeleza suluhisho za viwandani za kiotomatiki, zilizounganishwa kikamilifu na za kisasa katika sekta ya mimea na virutubisho. Kampuni imepitisha mfumo wa laini ya uzalishaji wa turnkey uliobinafsishwa, wa kiotomatiki, nadra, unaolingana na viwango vya GMP na ISO kwa uchimbaji, uwekaji kapsuli na utengenezaji wa vidonge vya Viambatanisho Amilifu vya Dawa (APIs) vinavyotokana na mimea. Usanidi huu tata na wa kiotomatiki wa kiviwanda ―TURNKEY ULTRASOUND-ASSISTED EXTRACTION (UAE), CAPSULE PRODUCTION AND TABLETING LINE SYSTEM‖ unachanganya mbinu tatu za hali ya juu za usindikaji:<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .05pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">1)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Mchakato wa uchimbaji na utakaso wa fitokemikali &ndash; Matibabu ya baada ya kuvuna, uondoaji wa mafuta iwezekanavyo, ukolezi, utakaso iwezekanavyo, ukaushaji wa utupu na ufungaji wa dondoo kwa uhifadhi;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">2)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Mchakato wa utengenezaji wa kapsuli &ndash; Uwekaji kapsuli, kujaza chupa, kufunga na kuziba, kuweka lebo kwenye chupa, kuweka kwenye sanduku la chupa, kuingiza kipeperushi na kuziba na kufungasha kwenye sanduku la chupa 15;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">3)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Mchakato wa utengenezaji wa vidonge &ndash; Kuchanganya dondoo kavu, uundaji wa chembe, ukaushaji wa utupu iwezekanavyo, kikausha cha kitanda cha maji, mgandamizo wa vidonge, upako wa vidonge, kujaza chupa, kufunga, kuziba chupa, kuweka lebo kwenye chupa, kuweka kwenye sanduku la chupa, kuingiza kipeperushi na ufungaji kwenye sanduku la chupa 15.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Mfumo wa laini hufanya kazi kwa joto la chini (40&ndash;60&deg;C) ili kuhifadhi viambatanisho amilifu vya dawa vinavyohisi joto (viumbe hai) vinavyolengwa kuunda dawa za mimea salama na bora, virutubisho, vyakula vya afya vilivyoimarishwa vyenye virutubisho vingi na mbolea za kikaboni zenye virutubisho vingi &ndash; teknolojia ya kisasa isiyo na kifani katika sekta ya TCAMs/dawa za mimea nchini Zambia.</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"color: red;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></p>', NULL, 0, '', '', '', '', '', 1, '2026-03-01 15:44:36', '', NULL, '2026-04-21 13:16:11', NULL, 1);
INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(112, 4, 'texte', 'ESG & Sustainability', 'ESG & Sustainability', 'ESG and sustainability', 'ESG na uendelevu', '', '', '', '', '<h2 style=\"margin-left: -0.25pt; padding-left: 120px;\"><span style=\"font-size: 18pt;\">(1)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Governance, Compliance &amp; Transparency</span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<h3 class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 80px;\"><span style=\"font-size: 14pt;\">AGF is committed to strong corporate governance, regulatory compliance, and financial transparency as foundational pillars of sustainable industrial growth.<strong style=\"mso-bidi-font-weight: normal;\"> </strong>The USD 40+ million capital deployment as seed capital prioritizes GMP (Good Manufacturing Practice)compliant infrastructure, ISO certification systems (<span style=\"line-height: 103%;\">ISO 9001, 22000, 14001, 45001 and 14644</span>), maintenance of annual independent financial audits, ESG (Environmental, Social and Governance) performance reporting, risk management oversight, and board-level governance structures, ensuring accountability and institutional integrity.<strong style=\"mso-bidi-font-weight: normal;\"> </strong></span></h3>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<h5 class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 320px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><em><span style=\"font-size: 14pt;\">Governance Commitments:</span></em></span></h5>\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]--><strong><span style=\"font-family: georgia, palatino, serif;\">Full GMP implementation and documentation</span></strong></span></em></span></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->ISO certification roadmap completion</span></em></span></strong></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->Annual independent financial audits</span></em></span></strong></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->ESG performance monitoring and reporting</span></em></span></strong></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->Structured compliance and risk management systems</span></em></span></strong></li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<h2 style=\"margin-left: -0.25pt; padding-left: 80px;\"><span style=\"font-size: 18pt;\">(2)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Institutional Oversight and Accountability</span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\">AGF Company operates under a structured corporate governance model that assures;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.55pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Clear separation between shareholders, Boards, and Executive Management</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.4pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Defined fiduciary responsibilities and delegated authority frameworks</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.4pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Independent advisory expertise in regulatory science, finance, ESG and risk management</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.15pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Structured board oversight on strategy, compliance and capital allocation</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\">This governance framework aligns with international best practices recognized by institutions such as International Finance Corporation and the World Bank.</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 200px;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<h2 style=\"margin-left: -0.25pt; padding-left: 80px;\"><span style=\"font-size: 18pt;\">(2) Regulatory Compliance, Quality Assurance &amp; Licensing</span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\">AGF is building an integrated compliance ecosystem aligned with international recognized standards, including but not limited to:</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.4pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 9001-Quality Management System</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.4pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 22000-Food Safety Management</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.5pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 14001- Environmental Governance and Sustainability</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.3pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 45001- Occupational Health &amp; Safety</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 15.35pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 14644- Cleanroom Qualification<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></strong></p>\r\n<ul>\r\n<li style=\"list-style-type: none;\">\r\n<ul>\r\n<li style=\"list-style-type: none;\">\r\n<ul>\r\n<li style=\"list-style-type: none;\">\r\n<ul style=\"list-style-type: square;\">\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 102%; font-weight: bold;\"><strong><span style=\"font-size: 14pt;\">Our production roadmap integrates Good Manufacturing Practices (GMP), </span></strong></li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 102%; font-weight: bold;\"><strong><span style=\"font-size: 14pt;\">validated laboratory systems, traceability controls, and regulatory documentation protocols required for&nbsp;<span style=\"mso-tab-count: 1;\"> </span>export-oriented <span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;</span></span></strong></li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 102%; font-weight: bold;\"><strong><span style=\"font-size: 14pt;\"><span style=\"mso-tab-count: 1;\">&nbsp;</span>TCAM, <span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Nutraceutical/Food <span style=\"mso-tab-count: 1;\"> </span>Supplement, <span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong></li>\r\n<li class=\"MsoNormal\" style=\"text-align: left; line-height: 102%; font-weight: bold;\"><strong><span style=\"font-size: 14pt;\">Phytomedicine&nbsp;<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp; </span>and Phytopharmaceutical, Fortified Clean-Label Health Food Product and Fruit Beverage regional and international markets.</span></strong></li>\r\n</ul>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 102%; margin: 0cm 0cm .2pt -.25pt;\" align=\"left\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 12pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 80px; text-align: left;\"><span style=\"font-size: 18pt;\"><strong><span style=\"color: rgb(45, 194, 107);\">AGF-PHYTOMED INDUSTRIES is subjected to the following regulatory licensing:</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 80px; text-align: left;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Business Application &amp; Registration &ndash;PACRA</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 0.85pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Investment Licence- ZDA</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 1.9pt 27.15pt; padding-left: 80px;\"><strong><span style=\"font-