INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(220, 15, 'grille_card', ' Our Investor & Partner Commitment', ' Our Investor & Partner Commitment', 'Our commitment to investors and partners', 'Ahadi yetu kwa wawekezaji na washirika', ' (Building Trust Through Transparency, Accountability, and Strategic Growth)', ' (Building Trust Through Transparency, Accountability, and Strategic Growth)', '(Building trust through transparency, accountability and strategic growth)', '(Kujenga uaminifu kupitia uwazi, uwajibikaji na ukuaji wa kimkakati)', '<ul>\r\n<li><span style=\"font-size: 24pt; font-family: \'arial black\', sans-serif;\"><strong><span style=\"line-height: 103%; color: black;\">Our Commitment to Investors, Donors &amp; Financial Brokers&nbsp;</span></strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">&nbsp; &nbsp;At AGF, we are dedicated to maximizing impact while ensuring financial integrity. Our approach combines:</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 18pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Non-fund Diversion Policy: Legally binding restricted use of proceeds covenant</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Transparency: Clear reporting of funds, expenditures, and project outcomes</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Accountability: Governance structures and audit-ready processes</span></p>\r\n</li>\r\n<li><span style=\"font-size: 24pt; line-height: 103%; font-family: \'arial black\', sans-serif; color: black;\"><strong>Financial Governance and Oversight&nbsp;</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">AGF adheres to international best practices in financial management, including:</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Independent audits and financial reviews</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Robust internal controls to safeguard assets</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Board-level oversight of all financial decisions</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Compliance with local and international regulations and reporting standards</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 14pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Investors and donors can trust that funds are managed efficiently, ethically, and in full compliance</span>.</span></p>\r\n</li>\r\n<li><span style=\"font-size: 24pt; font-family: \'arial black\', sans-serif;\"><strong><span style=\"line-height: 103%; color: black;\">Investment Opportunities </span></strong></span><br>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">AGF offers strategically structured investment opportunities designed to generate measurable returns while supporting health, nutrition, sustainable economic development and sustainable agriculture initiatives:</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Seed and growth-stage funding for AGF-PHYTOMED INDUSTRIES and digital platforms</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Co-investment opportunities with regional and international partners</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ESG-aligned projects focusing on preventive nutrition, functional foods, and organic farming of target medicinal plants, functional nutrient-dense crops, fruits and vegetables serving as raw materials for our manufacturing facility</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Investments are linked to clear KPIs and market expansion metrics, ensuring measurable impact and visibility.</span></p>\r\n</li>\r\n<li>\r\n<h2 style=\"margin-left: -.25pt;\"><span style=\"font-size: 24pt; font-family: \'arial black\', sans-serif;\"><strong>Donor Engagement and Impact</strong></span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">Donors are a critical part of AGF&rsquo;s mission. We provide:</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Regular impact reports highlighting social, environmental, and health outcomes</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Transparent tracking of funds toward community programs, research, and digital outreach</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Recognition of donors in line with preferences and contribution scale</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Donors can see how every contribution translates into real-world health, economic, gendersensitive job creation and social impact.</span></p>\r\n</li>\r\n<li><span style=\"font-size: 24pt; font-family: \'arial black\', sans-serif;\"><strong><span style=\"line-height: 103%; color: black;\"><span style=\"line-height: 103%; color: black;\">Financial Reporting and Transparency </span>&nbsp;</span></strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">AGF prioritizes real-time financial visibility:</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Quarterly and annual financial statements</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Online dashboards with project-wise and program-wise fund allocation</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Key Performance Indicator (KPI) tracking linked to market growth, community engagement, and ESG performance</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 18pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">This ensures investors and donors can monitor the impact of their support anytime.</span></p>\r\n</li>\r\n<li><span style=\"font-family: \'arial black\', sans-serif; font-size: 24pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"line-height: 103%; color: black;\">Why Partner With AGF? </span></strong></span><br>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"font-size: 18pt;\"><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Proven track record: 235+ WhatsApp groups, 211,500+ participants, growing daily</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->AI-driven digital marketing and community engagement for measurable reach</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Robust governance, compliance, and audit-ready processes</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Clear investment structure with ESG-aligned, high-impact projects</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Dedicated investor, donor &amp; broker relations team providing personalized support and reporting</span></p>\r\n</li>\r\n</ul>', '<ul>\r\n<li><span style=\"font-size: 24pt; font-family: \'arial black\', sans-serif;\"><strong><span style=\"line-height: 103%; color: black;\">Our Commitment to Investors, Donors &amp; Financial Brokers&nbsp;</span></strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">&nbsp; &nbsp;At AGF, we are dedicated to maximizing impact while ensuring financial integrity. Our approach combines:</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 18pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Non-fund Diversion Policy: Legally binding restricted use of proceeds covenant</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Transparency: Clear reporting of funds, expenditures, and project outcomes</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Accountability: Governance structures and audit-ready processes</span></p>\r\n</li>\r\n<li><span style=\"font-size: 24pt; line-height: 103%; font-family: \'arial black\', sans-serif; color: black;\"><strong>Financial Governance and Oversight&nbsp;</strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">AGF adheres to international best practices in financial management, including:</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Independent audits and financial reviews</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Robust internal controls to safeguard assets</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Board-level oversight of all financial decisions</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Compliance with local and international regulations and reporting standards</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 14pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Investors and donors can trust that funds are managed efficiently, ethically, and in full compliance</span>.</span></p>\r\n</li>\r\n<li><span style=\"font-size: 24pt; font-family: \'arial black\', sans-serif;\"><strong><span style=\"line-height: 103%; color: black;\">Investment Opportunities </span></strong></span><br>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">AGF offers strategically structured investment opportunities designed to generate measurable returns while supporting health, nutrition, sustainable economic development and sustainable agriculture initiatives:</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Seed and growth-stage funding for AGF-PHYTOMED INDUSTRIES and digital platforms</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Co-investment opportunities with regional and international partners</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ESG-aligned projects focusing on preventive nutrition, functional foods, and organic farming of target medicinal plants, functional nutrient-dense crops, fruits and vegetables serving as raw materials for our manufacturing facility</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Investments are linked to clear KPIs and market expansion metrics, ensuring measurable impact and visibility.</span></p>\r\n</li>\r\n<li>\r\n<h2 style=\"margin-left: -.25pt;\"><span style=\"font-size: 24pt; font-family: \'arial black\', sans-serif;\"><strong>Donor Engagement and Impact</strong></span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">Donors are a critical part of AGF&rsquo;s mission. We provide:</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Regular impact reports highlighting social, environmental, and health outcomes</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Transparent tracking of funds toward community programs, research, and digital outreach</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Recognition of donors in line with preferences and contribution scale</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Donors can see how every contribution translates into real-world health, economic, gendersensitive job creation and social impact.</span></p>\r\n</li>\r\n<li><span style=\"font-size: 24pt; font-family: \'arial black\', sans-serif;\"><strong><span style=\"line-height: 103%; color: black;\"><span style=\"line-height: 103%; color: black;\">Financial Reporting and Transparency </span>&nbsp;</span></strong></span>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">AGF prioritizes real-time financial visibility:</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Quarterly and annual financial statements</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Online dashboards with project-wise and program-wise fund allocation</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -9.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 9.0pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Key Performance Indicator (KPI) tracking linked to market growth, community engagement, and ESG performance</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 18pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 18pt;\">This ensures investors and donors can monitor the impact of their support anytime.</span></p>\r\n</li>\r\n<li><span style=\"font-family: \'arial black\', sans-serif; font-size: 24pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"line-height: 103%; color: black;\">Why Partner With AGF? </span></strong></span><br>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><!-- [if !supportLists]--><span style=\"font-size: 18pt;\"><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Proven track record: 235+ WhatsApp groups, 211,500+ participants, growing daily</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->AI-driven digital marketing and community engagement for measurable reach</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Robust governance, compliance, and audit-ready processes</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Clear investment structure with ESG-aligned, high-impact projects</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 18pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Dedicated investor, donor &amp; broker relations team providing personalized support and reporting</span></p>\r\n</li>\r\n</ul>', NULL, NULL, NULL, 0, '', NULL, NULL, NULL, '', 0, '2026-03-03 01:36:16', '', NULL, '2026-03-03 02:22:59', NULL, 1);
INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(221, 15, 'liste_card', 'Our Commitment to Investors, Donors & Financial Brokers', 'Our Commitment to Investors, Donors & Financial Brokers', 'Our commitment to investors, donors and financial brokers', 'Ahadi yetu kwa wawekezaji, wafadhili na madalali wa kifedha', 'At AGF, we are dedicated to maximizing impact while ensuring financial integrity. Our approach combines:', 'At AGF, we are dedicated to maximizing impact while ensuring financial integrity. Our approach combines:', 'At NUFOTEC, we are committed to maximizing impact while ensuring financial integrity. Our approach combines:', 'Katika NUFOTEC, tumejitolea kuongeza athari huku tukihakikisha uadilifu wa kifedha. Mbinu yetu inajumuisha:', '<ul>\r\n<li class=\"MsoNormal\" style=\"text-indent: -13.55pt; font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Non-fund Diversion Policy: Legally binding restricted use of proceeds covenant</strong></span></li>\r\n<li class=\"MsoNormal\" style=\"text-indent: -13.55pt; font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Transparency: Clear reporting of funds, expenditures, and project outcomes</strong></span></li>\r\n<li class=\"MsoNormal\" style=\"text-indent: -13.55pt; font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Accountability: Governance structures and audit-ready processes</strong></span></li>\r\n<li class=\"MsoNormal\" style=\"text-indent: -13.55pt; font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Sustainability: Long-term strategies for profitable, socially responsible, and ESG-aligned growth</strong></span></li>\r\n<li class=\"MsoNormal\" style=\"text-indent: -13.55pt; font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Our goal is to ensure every investment and donation directly contributes to market expansion, sustainable community development and health impact.</strong></span></li>\r\n</ul>', '<ul>\r\n<li class=\"MsoNormal\" style=\"text-indent: -13.55pt; font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Non-fund Diversion Policy: Legally binding restricted use of proceeds covenant</strong></span></li>\r\n<li class=\"MsoNormal\" style=\"text-indent: -13.55pt; font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Transparency: Clear reporting of funds, expenditures, and project outcomes</strong></span></li>\r\n<li class=\"MsoNormal\" style=\"text-indent: -13.55pt; font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Accountability: Governance structures and audit-ready processes</strong></span></li>\r\n<li class=\"MsoNormal\" style=\"text-indent: -13.55pt; font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Sustainability: Long-term strategies for profitable, socially responsible, and ESG-aligned growth</strong></span></li>\r\n<li class=\"MsoNormal\" style=\"text-indent: -13.55pt; font-weight: bold; font-size: 14pt;\"><span style=\"font-size: 14pt;\"><strong>Our goal is to ensure every investment and donation directly contributes to market expansion, sustainable community development and health impact.</strong></span></li>\r\n</ul>', NULL, NULL, NULL, 0, '', NULL, NULL, NULL, '', 1, '2026-03-03 01:45:01', '', NULL, '2026-03-03 02:24:01', '2026-03-03 02:24:01', 1),
(222, 15, 'grille_card', ' Financial Governance and Oversight', ' Financial Governance and Oversight', 'Financial governance and oversight', 'Utawala wa kifedha na usimamizi', 'AGF adheres to international best practices in financial management, including:', 'AGF adheres to international best practices in financial management, including:', 'NUFOTEC adheres to international best practices in financial management, including:', 'NUFOTEC inafuata mbinu bora za kimataifa katika usimamizi wa kifedha, ikijumuisha:', '<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l4 level1 lfo2; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Independent audits and financial reviews</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l4 level1 lfo2; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Robust internal controls to safeguard assets</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l4 level1 lfo2; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Board-level oversight of all financial decisions</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l4 level1 lfo2; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Compliance with local and international regulations and reporting standards</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l4 level1 lfo2; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Investors and donors can trust that funds are managed efficiently, ethically, and in full compliance.</strong></span></p>', '<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l4 level1 lfo2; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Independent audits and financial reviews</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l4 level1 lfo2; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span>Robust internal controls to safeguard assets</strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.55pt; mso-list: l4 level1 lfo2; margin: 0cm 0cm .85pt 13.55pt;\"><span style=\"font-size: 14pt;\"><strong><span style=\"mso-bidi-font-size: 14.0pt; line-heigh