INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `titre_section_fr`, `titre_section_en`, `titre_section_sw`, `sous_titre`, `sous_titre_fr`, `sous_titre_en`, `sous_titre_sw`, `contenu_texte`, `contenu_texte_fr`, `contenu_texte_en`, `contenu_texte_sw`, `image_url`, `image_droite`, `bouton_texte`, `bouton_texte_fr`, `bouton_texte_en`, `bouton_texte_sw`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(240, 23, 'hero', 'WELCOME', 'WELCOME', 'WELCOME', 'KARIBU', 'Good Choice TO Become Our Capital Introducer', 'Good Choice TO Become Our Capital Introducer', 'Good choice to become our capital introduction intermediary', 'Chaguo nzuri kuwa mpatanishi wetu wa utangulizi wa mtaji', '', '', NULL, NULL, '/attachments/Sections/2026030418202369a85bc772720.jpg', 0, '', NULL, NULL, NULL, '', 1, '2026-03-04 18:20:24', '', NULL, NULL, NULL, 1),
(241, 23, 'texte', 'Expression of Interest (EOI) Form', 'Expression of Interest (EOI) Form', 'Expression of interest form', 'Fomu ya kuelezea nia', 'Expression of Interest (EOI) Form', 'Expression of Interest (EOI) Form', 'Expression of interest form', 'Fomu ya kuelezea nia', '<p>AFRICAN GREEN FARMERS LTD (AGF) invites qualified and compliant capital intermediaries to register their interest in supporting the mobilization of strategic funding for its integrated agro-industrial, bioeconomy and phytopharmaceutical development programs.</p>\r\n<p>This registration is directed to AFRICAN GREEN FARMERS LTD as the principal entity.</p>\r\n<p>Submission of this form does not constitute a mandate, exclusivity, or legally binding engagement. Any collaboration is subject to due diligence and execution of a formal agreement.</p>', '<p>AFRICAN GREEN FARMERS LTD (AGF) invites qualified and compliant capital intermediaries to register their interest in supporting the mobilization of strategic funding for its integrated agro-industrial, bioeconomy and phytopharmaceutical development programs.</p>\r\n<p>This registration is directed to AFRICAN GREEN FARMERS LTD as the principal entity.</p>\r\n<p>Submission of this form does not constitute a mandate, exclusivity, or legally binding engagement. Any collaboration is subject to due diligence and execution of a formal agreement.</p>', '<p>AFRICAN GREEN FARMERS LTD (NUFOTEC) invites qualified and compliant capital intermediaries to register their interest in supporting strategic fundraising for its integrated agro-industrial, bioeconomy and phytopharmaceutical development programs.</p>\n<p>This registration is addressed to AFRICAN GREEN FARMERS LTD as the lead entity.</p>\n<p>Submission of this form does not constitute a mandate, exclusivity or legally binding commitment. Any collaboration is subject to due diligence and the signing of a formal agreement.</p>', '<p>AFRICAN GREEN FARMERS LTD (NUFOTEC) inakaribisha wapatanishi wa mtaji waliohitimu na wanaofuata kanuni kusajili nia yao ya kusaidia ufadhili wa kimkakati kwa programu zake zilizojumuishwa za maendeleo ya kilimo-viwanda, uchumi wa kibayolojia na dawa za mimea.</p>\n<p>Usajili huu unaelekezwa kwa AFRICAN GREEN FARMERS LTD kama shirika linaloongoza.</p>\n<p>Uwasilishaji wa fomu hii haujumuishi mamlaka, upekee au dhamira ya kisheria inayofunga. Ushirikiano wowote unategemea uchunguzi wa kina na kusainiwa kwa makubaliano rasmi.</p>', NULL, 0, '', NULL, NULL, NULL, '', 1, '2026-03-04 18:21:33', '', NULL, NULL, NULL, 1),
(242, 24, 'hero', 'WELCOME', 'WELCOME', 'WELCOME', 'KARIBU', 'INVEST IN US OR BECOME A CONTRACTUAL BROKER WITH US TODAY !?', 'INVEST IN US OR BECOME A CONTRACTUAL BROKER WITH US TODAY !?', 'INVEST IN US OR BECOME OUR CONTRACTUAL BROKER TODAY!?', 'WEKEZA KWETU AU KUWA DALALI WETU WA KANDARASI LEO!?', '', '', NULL, NULL, '/attachments/Sections/2026030421081669a88320c4170.jpg', 0, '', NULL, NULL, NULL, '', 0, '2026-03-04 21:08:16', '', NULL, NULL, NULL, 1);

-- --------------------------------------------------------

--
-- Structure de la table `services`
--

DROP TABLE IF EXISTS `services`;
CREATE TABLE IF NOT EXISTS `services` (
  `id_service` int NOT NULL AUTO_INCREMENT,
  `titre` varchar(255) NOT NULL,
  `description` text,
  `icone` varchar(50) DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `lien` varchar(500) DEFAULT NULL,
  `ordre` int DEFAULT '0',
  `id_page_associee` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_service`),
  KEY `id_page_associee` (`id_page_associee`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=latin1;

