--
-- Structure de la table `user_activities`
--

DROP TABLE IF EXISTS `user_activities`;
CREATE TABLE IF NOT EXISTS `user_activities` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` int UNSIGNED DEFAULT NULL,
  `action` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type d''action (login, logout, create, update, delete, view, etc.)',
  `module` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Module concerné (users, produits, commandes, etc.)',
  `item_id` int UNSIGNED DEFAULT NULL COMMENT 'ID de l''élément concerné',
  `item_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nom de l''élément concerné',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Description détaillée de l''action',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` text COLLATE utf8mb4_unicode_ci,
  `old_data` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Anciennes données (JSON)',
  `new_data` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Nouvelles données (JSON)',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `user_activities_user_id_foreign` (`user_id`),
  KEY `user_activities_module_index` (`module`),
  KEY `user_activities_action_index` (`action`),
  KEY `user_activities_created_at_index` (`created_at`),
  KEY `user_activities_item_id_index` (`item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=120 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

