-- --------------------------------------------------------

--
-- Structure de la table `user_subscriptions`
--

DROP TABLE IF EXISTS `user_subscriptions`;
CREATE TABLE IF NOT EXISTS `user_subscriptions` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` int UNSIGNED NOT NULL COMMENT 'Référence vers users.id',
  `plan_id` int UNSIGNED NOT NULL,
  `date_debut` datetime NOT NULL,
  `date_fin` datetime NOT NULL,
  `statut` enum('actif','expire','annule') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'actif',
  `prix_applique` decimal(15,2) NOT NULL COMMENT 'Prix payé',
  `devise_appliquee` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pays_id` int UNSIGNED DEFAULT NULL COMMENT 'Pays de l’utilisateur à la souscription',
  `payment_method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transaction_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_status` (`user_id`,`statut`),
  KEY `idx_date_fin` (`date_fin`),
  KEY `fk_user_subscriptions_plan` (`plan_id`),
  KEY `fk_user_subscriptions_pays` (`pays_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `violations_log`
--

DROP TABLE IF EXISTS `violations_log`;
CREATE TABLE IF NOT EXISTS `violations_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `phone_number` varchar(50) NOT NULL,
  `violation_type` varchar(50) NOT NULL,
  `message_content` text,
  `message_id` varchar(255) DEFAULT NULL,
  `groupe_id` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `phone_number` (`phone_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Structure de la table `visitors_logs`
--

DROP TABLE IF EXISTS `visitors_logs`;
CREATE TABLE IF NOT EXISTS `visitors_logs` (
  `id` int NOT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_general_ci NOT NULL,
  `user_agent` text COLLATE utf8mb4_general_ci,
  `device` enum('Mobile','Desktop','Other') COLLATE utf8mb4_general_ci DEFAULT 'Desktop',
  `page` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `referer` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `visit_date` date NOT NULL,
  `visit_time` time NOT NULL,
  `country` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `city` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `latitude` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `longitude` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

