-- --------------------------------------------------------

--
-- Structure de la table `wa_messages_queue`
--

DROP TABLE IF EXISTS `wa_messages_queue`;
CREATE TABLE IF NOT EXISTS `wa_messages_queue` (
  `id` int NOT NULL AUTO_INCREMENT,
  `message` text,
  `sender_number` varchar(20) DEFAULT NULL,
  `sender_name` varchar(255) DEFAULT NULL,
  `is_admin` tinyint(1) DEFAULT '0',
  `broadcast_type` enum('groups','inbox','both') DEFAULT 'groups',
  `media_type` enum('text','image','video','audio','document','sticker','location','contact') DEFAULT 'text',
  `media_id` varchar(255) DEFAULT NULL,
  `media_url` varchar(500) DEFAULT NULL,
  `media_caption` text,
  `media_filename` varchar(255) DEFAULT NULL,
  `media_mime_type` varchar(100) DEFAULT NULL,
  `media_latitude` varchar(50) DEFAULT NULL,
  `media_longitude` varchar(50) DEFAULT NULL,
  `media_contacts` text,
  `status` enum('pending','processing','sent','failed','cancelled') DEFAULT 'pending',
  `retries` int DEFAULT '0',
  `max_retries` int DEFAULT '3',
  `last_error` text,
  `total_recipients` int DEFAULT '0',
  `sent_count` int DEFAULT '0',
  `scheduled_at` datetime DEFAULT NULL,
  `processed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `status` (`status`),
  KEY `scheduled_at` (`scheduled_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Structure de la table `whatsapp_logs`
--

DROP TABLE IF EXISTS `whatsapp_logs`;
CREATE TABLE IF NOT EXISTS `whatsapp_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_request_id` int DEFAULT NULL COMMENT 'ID de la commande associée',
  `product_id` int DEFAULT NULL,
  `phone_number` varchar(50) NOT NULL COMMENT 'Numéro destinataire',
  `message_content` text NOT NULL COMMENT 'Contenu du message',
  `message_type` enum('price_request','order_confirmation','other') DEFAULT 'order_confirmation',
  `status` enum('sent','failed','pending') DEFAULT 'pending',
  `error_message` text COMMENT 'Message d''erreur si échec',
  `sent_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_order_request_id` (`order_request_id`),
  KEY `idx_product_id` (`product_id`)
) ENGINE=MyISAM AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

